#!/usr/bin/env python3
import base64,gzip,json,sys
from pathlib import Path
PAYLOAD = "[... ELLIPSIZATION ...]"
def main():
    files=json.loads(gzip.decompress(base64.b64decode(PAYLOAD)).decode())
    if len(sys.argv)==2 and sys.argv[1]=="--list":
        print("\n".join(sorted(files)))
        return
    if len(sys.argv)!=2: raise SystemExit("usage: core369_payload.py DEST | --list")
    dest=Path(sys.argv[1]).resolve()
    for rel,content in files.items():
        path=(dest/rel).resolve()
        if not str(path).startswith(str(dest)+"/"): raise SystemExit(f"unsafe path: {rel}")
        path.parent.mkdir(parents=True,exist_ok=True)
        path.write_text(content)
    print(json.dumps({"status":"extracted","files":len(files)}))
if __name__=="__main__": main()
